import SwiftUI

struct AppIconAssets {
    // ใส่ Base64 String ของรูปภาพที่ต้องการที่นี่
    static let appIconBase64 = """
    
    """

    // Convert Base64 เป็น SwiftUI Image
    static var appIcon: Image? {
        guard let data = Data(base64Encoded: appIconBase64),
              let uiImage = UIImage(data: data) else {
            return nil
        }
        return Image(uiImage: uiImage)
    }
}
